package test

import game.scene.PlayerClimbContact
import java.io.File
import javax.imageio.ImageIO
import kotlin.test.*

/**
 * PlayerClimbContact (generated by tools/art/prep_climb_contact.py) against the climb frames on
 * disk: with each frame's corner point on the box's top corner, the figure is not drawn inside the
 * box ("he is going inside the platform"), something of him rests on its top ("not touching the top
 * part"), and the hands reach over the lip while he hangs and pulls up. Catches a re-cut clip that
 * was not re-solved.
 */
class PlayerClimbContactTest {

    private fun frame(f: Int) = ImageIO.read(File("art/frames/player/climb/${(70 + f).toString().padStart(4, '0')}.png"))

    @Test
    fun testEverySolvedFrameRestsOnTheBoxWithoutGoingIntoIt() {
        var previous: Pair<Int, Int>? = null
        for (f in 0..PlayerClimbContact.FADE_TO) {
            val img = frame(f)
            assertEquals(PlayerClimbContact.FRAME_WIDTH, img.width, "climb frame ${70 + f} width")
            assertEquals(PlayerClimbContact.FRAME_HEIGHT, img.height, "climb frame ${70 + f} height")
            val u = PlayerClimbContact.u(f)
            val v = PlayerClimbContact.v(f)
            fun solid(x: Int, y: Int) = ((img.getRGB(x, y) ushr 24) and 0xFF) > 128
            var inside = 0
            var lowestOver = -1
            var front = -1
            for (y in 0 until img.height) for (x in 0 until img.width) {
                if (!solid(x, y)) continue
                if (x > front) front = x
                if (x < u) continue
                if (y >= v) inside++ else if (y > lowestOver) lowestOver = y
            }
            val raw = 70 + f
            // Hanging and pulling up nothing goes in; the feet swinging over the lip (raw ~149) may
            // clip its corner for a frame - a toe's worth.
            assertTrue(inside <= if (raw <= 140) 10 else 40, "raw $raw: $inside px drawn inside the box")
            assertTrue(inside > 0 || v - (lowestOver + 1) <= 2, "raw $raw: nothing rests on the deck (gap ${v - lowestOver - 1} px)")
            if (raw <= 140) assertTrue(front - u >= 1, "raw $raw: the hands reach over the lip")
            previous?.let { (pu, pv) ->
                val step = kotlin.math.abs(u - pu) + kotlin.math.abs(v - pv)
                assertTrue(step <= 25, "raw $raw: the figure jumps $step px against the box")
            }
            previous = u to v
        }
    }

    @Test
    fun testTheTableHandsBackToPlayerOverItsFade() {
        assertEquals(1.0, PlayerClimbContact.weight(0))
        assertEquals(1.0, PlayerClimbContact.weight(PlayerClimbContact.FADE_FROM))
        assertEquals(0.0, PlayerClimbContact.weight(PlayerClimbContact.FADE_TO))
        assertEquals(0.0, PlayerClimbContact.weight(154))
        val mid = PlayerClimbContact.weight((PlayerClimbContact.FADE_FROM + PlayerClimbContact.FADE_TO) / 2)
        assertTrue(mid > 0.0 && mid < 1.0)
    }
}
